describe("Rust <-> TS pipe contract parity", () => {
  test("fixtures protocol version matches the TS codec", () => {
    expect(fixtures.protocol_version).toBe(PROTOCOL_VERSION);
  });

  test("fixtures cover exactly the TS message set", () => {
    const fixtureNames = new Set(fixtures.cases.map((c) => c.name));
    const tsNames = new Set(Object.keys(MESSAGES));
    expect([...fixtureNames].sort()).toEqual([...tsNames].sort());
  });

  for (const c of fixtures.cases) {
    test(`${c.name}: TS encodes to the canonical bytes`, () => {
      const msg = MESSAGES[c.name];
      expect(msg, `no TS message for fixture '${c.name}'`).toBeDefined();

      const env = encodeMessage(msg);
      expect(hex(env)).toBe(c.envelope_hex);

      const frame = encodeFrame(env);
      expect(hex(frame)).toBe(c.frame_hex);
    });

    test(`${c.name}: TS decodes the canonical bytes back`, () => {
      const decoded = decodeMessage(fromHex(c.envelope_hex));
      const expected = MESSAGES[c.name];
      // Normalize binary payloads to plain arrays for structural comparison.
      expect(normalize(decoded)).toEqual(normalize(expected));
    });
  }
});

// Make Uint8Array payloads comparable across encode/decode (bun's toEqual treats
// Uint8Array and number[] differently).
function normalize(m: Message): unknown {
  if (m.category === "event" && m.kind === "terminal_output") {
    return { ...m, data: Array.from(m.data) };
  }
  if (m.category === "request" && m.kind === "pty_write") {
    return { ...m, data: Array.from(m.data) };
  }
  if (m.category === "event" && m.kind === "command_output") {
    return { ...m, data: Array.from(m.data) };
  }
  return m;
}
